\section{An improved bound: Proof of~\Cref{thm:rsquared-overview}}

In this section we prove: 

\begin{theorem}[\Cref{thm:rsquared-overview} with a dependence on $N$]  
\label{thm:rsquared-bound}
Let $\mathcal{A}$ be a $t$-parallel $d$-round quantum algorithm and $f : \zo^N \to [0,1]$ denote its acceptance probabilities. If $\mathcal{A}$ is $\eta$-regular where 
\[ \eta \le 2^{-\Omega(d^2)}\cdot (t\log N)^{-\Omega(d)}\cdot \log(1/\delta)^{-1}, \] 
then $\min\{\Pr[\Acc_f],\Pr[\Rej_f]\}\le \delta$. 
    \end{theorem}

\violet{
Again, the statement of~\Cref{thm:rsquared-bound} does not quite match that of~\Cref{thm:rsquared-overview} due to the dependence on $N$, but as mentioned, in~\Cref{sec:removing dependence on $N$} we will show that this dependence can be generically removed by setting $N = \poly(2^{td},1/\delta)$.  In the setting of~\Cref{thm:rsquared-bound} this amounts to replacing $\log N$ with $\log(1/\delta)$, which then yields~\Cref{thm:rsquared-overview}.}

\pparagraph{Proof overview.}
As discussed in \Cref{subsec:overview-improved}, this proof will rely on the following notion of \emph{distance}: For any distribution $\mcD$ and $x,y$, we denote,
\begin{equation*}
    \dist_{\mcD}(x,y) \coloneqq \Prx_{\bS \sim \mcD}[x_{\bS} \neq y_{\bS}],
\end{equation*}
and similarly, for set $A$,
\begin{equation*}
    \dist_{\mcD}(x, A) \coloneqq \min_{y \in A} \dist_{\mcD}(x, y).
\end{equation*}

This definition aligns with \Cref{eq:dist-bound-layer,eq:final_condition_implies_total_progress_2}: For any $x\in \Acc$, there is some round $r\in [d]$ for which $$\dist_{\mcD_x^{(r)}}(x, \Rej) \geq \poly(1/r).$$
Similarly, \Cref{eq:dist-bound-layer} means that if $\mcD_x^{(r)}$ and $\mcD_y^{(r)}$ are ``far" (i.e. distinguishable by some test), then there must be some $r' \leq r$ for which $\dist_{\mcD_x^{(r')}}(x,y)$ is large.

For the warm-up (\Cref{lem:warmup-overview}), we formalized the notion of $\mcD^{(r)}_x$ as being ``concentrated" by having a single coordinate $i \in [N]$ that commonly appears in $\bS \sim \mcD^{(r)}$. Our  proof of~\Cref{thm:rsquared-bound} requires a more general definition: 
\begin{definition}[$(m,\gamma)$-hit and spread] 
\label{def:hit-spread}
    For $m \in [N]$ and $\gamma \in [0,1]$, we say that a distribution $\mcD$ over subsets of $[N]$ is {\sl $(m,\gamma)$-hit} if 
    \begin{equation*}
        \Prx_{\bS \sim \mcD}[\bS \cap T \neq \emptyset] \geq \gamma\quad \text{for some $T\sse [N]$ of size $m$.}
    \end{equation*}
    We will also say a distribution is $(m, \gamma)$-\textsl{spread} if it is not $(m,\gamma)$-\textsl{hit}, meaning there is no $T$ of size $m$ for which the above inequality holds.
\end{definition}
\violet{The most technical portion of this proof connects these notions of distance and concentration, showing that for a distribution to separate large sets, it must be concentrated.}

\begin{restatable}[Large distance implies hitting]{lemma}{DistToHit}
    \label{lem:dist-to-hit}
    Let $A\sse \zo^N$ be any set, and for each $x\in \zo^N$ let $\mcD_x$ be a distribution over subsets of $[N]$ of size at most $t$. For any $m\in [N]$ and $0 < \gamma < \tau$, 
\begin{equation*}
        \Pr[A] \cdot \Pr\big[
            \dist_{\mcD_{\bx}}(\bx, A) \geq \tau\text{ and }
            \mathcal D_{\bx}\ \text{is }(m,\gamma)\text{-spread}\,
        \big] \leq \exp\paren*{-\Omega\paren*{\frac{(\tau-\gamma)^2m}{\gamma t}}}.
    \end{equation*}
\end{restatable}

Using this, we will prove the two main lemmas, the analogues of~\Cref{lem:regularity implies few bad inputs,lem:good inputs are biased} in our warm-up. First, we will define parameters,
\begin{equation*}
    m_1 \geq \cdots \geq m_d \quad\quad\text{and}\quad\quad \gamma_1 \leq \cdots \leq \gamma_d
\end{equation*}
and for each round $r\in [d]$, the sets
\begin{equation}
    \label{eq:def-bad-good}
    \Bad^{(r)} \coloneqq \set{x : \mcD_x^{(r)} \text{ is $(m_r,\gamma_r)$-hit}} \quad\text{and}\quad \Good^{(\leq r)} \coloneqq \zo^N \setminus \bigcup_{r' \in [r]}\Bad^{(r')}.
\end{equation}
Note the direction of monotonicity: At lower layers, we have larger values for $m$ and smaller values of $\gamma$. Both of these correspond to a more stringent constraint in order to be in $\Good$. Our first bound uses this monotonicity to bound the number of bad inputs:
\begin{restatable}[Regularity $\Rightarrow$ Few bad inputs]{lemma}{BoundBadStronger}
    \label{lem:most-inputs-good}
    For any $r\in \{ 2,\ldots,d\}$, if the regularity parameter $\eta$ satisfies
  $\eta \leq \gamma_r/(4m_r)$ where 
    \begin{equation*}
        \gamma_r \geq \Omega\paren[\Bigg]{\sum_{r' \in [r-1]} \gamma_{r'} \cdot (r-r')^2}, 
    \end{equation*}
    then
    \begin{equation*}
        \Pr\bracket*{\Bad^{(r)} \cap \Good^{(\leq r-1)}} \leq \binom{N}{m_r} \cdot \exp\paren*{-\Omega\paren*{\frac{\gamma_r m_{r-1} }{tr^3}}}
    \end{equation*}    
\end{restatable}

With~\Cref{lem:most-inputs-good} in hand, a bound on $\Pr[\Bad^{(\le d)}]$ follows easily via a union bound.
The second lemma then says that if this probability is small, the function must be biased: 
\begin{restatable}[\violet{Good inputs are biased}]{lemma}{GoodToBiased}
    \label{lem:bound-var}
    There is an absolute constant $c$ such that if 
    \begin{equation}
        \label{eq:sum-biased}
        \sum_{r \in [d]} (d-r+1)^2 \cdot \gamma_r \leq c,
    \end{equation}
    then
    \begin{equation*}
        \Pr\big[\Acc\big] \cdot \Pr\big[\Rej \cap \Good^{(\leq d)}\big] \leq \exp\paren*{-\Omega\paren*{\frac{m_d}{td^3}}}.
    \end{equation*}
\end{restatable}

\paragraph{Structure of this section.} We prove~\Cref{lem:dist-to-hit} in~\Cref{sec:dist-to-hit}, \Cref{lem:most-inputs-good} in~\Cref{sec:most-inputs-good}, and~\Cref{lem:bound-var} in~\Cref{sec:lem:bound-var}.  In~\Cref{sec:rsquared-bound} we put everything together to prove~\Cref{thm:rsquared-bound}. 

\subsection{Large distance implies hitting: Proof of \Cref{lem:dist-to-hit}}
\label{sec:dist-to-hit}

To prove~\Cref{lem:dist-to-hit}, we analyze the natural greedy algorithm that builds a size-$m$ set $T$ that $\gamma$-hits $\mcD_x$, under the assumption that $\dist_{\mcD_x}(x,A) \geq \tau$. At each step, this greedy algorithm picks the variable that overlaps with the largest fraction of $\bS\sim \mcD_x$. The following helps quantify the progress we make at each step: 

\begin{claim}
    \label{claim:dist-to-heavy-element}
    Let $\mcD$ be a distribution supported on subsets of $[N]$ of size at most $t$. \violet{For any input $x \in \zo^N$ and set $A \subseteq \zo^N$, there exists an $i\in [N]$ such that }
    \begin{equation*}
        \Prx_{\bS \sim \mcD}[i \in \bS] \geq \frac{\violet{\dist_{\mcD}(x,A)^2}}{t \cdot \dtal(x,A)^2}.
    \end{equation*}
\end{claim}
The proof of \Cref{claim:dist-to-heavy-element} is analogous to that of \Cref{cor:talagrand-linf}. We give it in \Cref{subsec:dist-to-heavy-element}. For now, we show how to use it to prove \Cref{lem:dist-to-hit}.
\subsubsection{Proof of \Cref{lem:dist-to-hit} assuming \Cref{claim:dist-to-heavy-element}} 
We begin by initializing $T^{(0)} = \emptyset$. At each step $j = 1,2,\ldots$, we set
    \begin{equation*}
        i_j \coloneqq \argmax_{i \in [N]} \Prx_{\bS \sim \mcD_x} \bracket*{i \in \bS \text{ and }\bS \cap T^{(j-1)} = \emptyset},
    \end{equation*}
    and let $T^{(j)} \coloneqq T^{(j-1)} \cup \set{i_j}$. We stop at the first time step $m^{\star}$ at which $T^{(m^{\star})}$ $\gamma$-hits $\mcD_x$. We also define $\mcD^{(j)}$ to be the distribution over subsets $\bS'$ formed by first drawing $\bS \sim \mcD_x$ and setting
    \begin{equation*}
        \bS' \coloneqq \begin{cases}
        \bS &\text{if }\bS \cap T^{(j)} = \emptyset \\
        \emptyset&\text{otherwise.}
        \end{cases}
    \end{equation*}
    Given this notation, we can write
    \begin{align}
        \Prx_{\bS \sim \mcD_x}\bracket*{\bS \cap T^{(m^{\star})} \neq \emptyset} &= \sum_{j \in [m^{\star}]} \Prx_{\bS \sim \mcD_x} \bracket*{i_j \in \bS \text{ and }\bS \cap T^{(j-1)} = \emptyset} \notag \\
        &= \sum_{j \in [m^{\star}]} \Prx_{\bS \sim \mcD^{(j-1)}} \bracket*{i_j \in \bS} \notag \\
        &=\sum_{j \in [m^{\star}]} \argmax_{i \in [N]} \Prx_{\bS \sim \mcD^{(j-1)}} \bracket*{i \in \bS}. \label{eq:sum arg max}
    \end{align}
    We wish to apply \Cref{claim:dist-to-heavy-element} to conclude that each term in the above sum must be large. To do so, we observe that
    \begin{equation*}
        \dist_{\mcD^{(j)}}(x, A) \geq \dist_{\mcD_x}(x, A) - \dtv(\mcD_x, \mcD^{(j)})
    \end{equation*}
    Furthermore, we have defined $m^{\star}$ to be the first time step for which $T^{(m^{\star})}$ $\gamma$-hits $\mcD_x$. This means that $\dtv(\mcD_x, \mcD^{(j)}) \leq \gamma$ 
    for every $j < m^{\star}$. We can therefore apply~\Cref{claim:dist-to-heavy-element} to~\Cref{eq:sum arg max} to get: 
    \begin{equation*}
        \Prx_{\bS \sim \mcD_x}\bracket*{\bS \cap T^{(m^{\star})} \neq \emptyset} \geq m^{\star} \cdot \frac{\max\set{0,\dist_{\mcD_x}(x, A) - \gamma}^2}{t \cdot \dtal(x,A)^2}.
    \end{equation*}
    Finally, we observe that if $\dist_{\mcD_x}(x,A) \geq \tau$ and $\dtal(x,A) \leq  \sqrt{\frac{(\tau-\gamma)^2\,m}{\gamma t}}$, then for $m^{\star} = m$, the above will be at least $\gamma$, which means that $\mcD_x$ is $(m,\gamma)$-hit. Therefore,
    \begin{equation*}
        \Pr\bracket*{
            \dist_{\mcD_{\bx}}(\bx, A) \geq \tau\text{ and }
            \mathcal D_{\bx}\ \text{is }(m,\gamma)\text{-spread}
        } \leq \Pr\bracket*{\dtal(x,A) > \sqrt{\lfrac{(\tau-\gamma)^2\,m}{\gamma t}}},
    \end{equation*}
and Talagrand's convex-distance inequality (\Cref{thm:Talagrand}) gives the desired result.

\subsubsection{Proof of \Cref{claim:dist-to-heavy-element}}
\label{subsec:dist-to-heavy-element}

    Let $w \in \R^N_{\ge 0}$ be the vector $w_i \coloneqq \Prx_{\bS \sim \mcD}[i \in \bS]$. Since $\mcD$ is supported on subsets of size at most $t$, we have $\lone{w} \leq t$. Our goal is to lower bound $\linf{w}$. We first apply H\"older's inequality
    \begin{equation}
        \label{eq:Holder}
        \linf{w} \geq \frac{\ltwo{w}^2}{\lone{w}} \geq \frac{\ltwo{w}^2}{t},
    \end{equation}
    which reduces our task to that of lower bounding $\ltwo{w}$. To do so, we first show that \violet{$\dist_{w}(x,A) \geq \dist_{\mcD}(x,A)$. It suffices to show the inequality for every $y \in A$,
    \begin{equation*}
        \dist_{\mcD}(x,y) =  \Prx_{\bS\sim\mcD}[x_{\bS}\ne y_{\bS}] \le \sum_{i\in \Delta(x,y)} \Prx_{\bS\sim\mcD}[i\in \bS] = \sum_{i\in\Delta(x,y)}w_i = \dist_w(x,y).
    \end{equation*}}  
    Finally, let $\tilde{w} = \frac{w}{\ltwo{w}}$, and so \[ d_{\tilde{w}}(x,A) \geq \frac{\dist_{\mcD}(x,A)}{\ltwo{w}}.\] This normalization ensures  $\tilde{w}$ is included in the supremum in the definition of $\dt$ (recall \Cref{thm:Talagrand}), and so $d_{\tilde{w}}(x,A) \leq  \dt(x,A)$. Combining these, we get: 
    \begin{equation*}
       \frac{\dist_{\mcD}(x,A)}{\ltwo{w}} \leq d_{\tilde{w}}(x,A) \leq \dtal(x,A),
    \end{equation*}
This along with~\Cref{eq:Holder} completes the proof.



\subsection{Regularity implies few bad inputs: Proof of \Cref{lem:most-inputs-good}}
\label{sec:most-inputs-good}
Our proof will use the following method of combining $\mcD^{(1)}_x,\ldots,\mcD^{(r)}_x$ into a single distribution. This choice is made because the series $\sum_{i}^{r} 1/i^2$ converges for any choice of $r$ and also no individual term is smaller than $1/\poly(r)$. The convergence ensures that \Cref{claim:combine-dist-exp} holds, whereas the fact that no term is too small ensures the $r^3$ term in \Cref{lem:most-inputs-good} is mild.

\begin{claim}
    \label{claim:combine-dist-exp}
     For any $x\in \zo^N$ and $r\in [d]$ we define $\mcD^{(\quads,r)}_x$ to be the product distribution
    \begin{equation}
        \label{eq:def-quad-dist}
        \mcD^{(\quads,r)}_x \coloneqq \paren*{\mcD_x^{(1)}}^{r^2} \times \paren*{\mcD_x^{(2)}}^{(r-1)^2} \times \cdots \times \paren*{\mcD_x^{(r-1)}}^{2^2}\times \paren*{\mcD_x^{(r)}}^{1^2}.
    \end{equation}
    Then for $y\in \zo^N$, 
    \begin{equation}
        \label{eq:compare-exp}
        \Prx_{\bS \sim \mcD^{(\quads,r)}_x}[x_{\bS} \neq y_{\bS}] \geq \lfrac{1}{3}\cdot \min\set*{1,\paren[\Bigg]{\sum_{r' \in [r]}\sqrt{\Prx_{\bS \sim \mcD^{(r')}_x}\bracket*{x_{\bS} \neq y_{\bS}}}}^2}.
    \end{equation}
\end{claim}
Note that the right-hand side of \Cref{eq:compare-exp} is the quantity we can bound using \Cref{eq:dist-bound-layer,eq:final_condition_implies_total_progress_2}. We will also need a simple proposition: 
\begin{proposition}
    \label{prop:combine-dist-hit} 
    Let $\gamma = \sum_{r' \in [r]} \gamma_{r'} \cdot (r-r' + 1)^2$. For all $x \in \zo^N$, 
    \begin{equation*}
        x \in \Good^{(\leq r)} \implies \mcD^{(\quads,r)}_x\text{ is }(m_r,\gamma)\text{-spread}.
    \end{equation*}
\end{proposition}


We prove \Cref{claim:combine-dist-exp} in \Cref{subsec:combine-dists} and \Cref{prop:combine-dist-hit} in \Cref{subsec:proof-of-combine-dist-hit}. For now, we use them to prove~\Cref{lem:most-inputs-good}. 

\subsubsection{Proof of~\Cref{lem:most-inputs-good} assuming~\Cref{claim:combine-dist-exp} and~\Cref{prop:combine-dist-hit}}

    In order for $x$ to be in $\Bad^{(r)}$, there must exist some $|T| = m_r$ for which $\Prx_{\bS \sim \mcD^{(r)}_x}[\bS \cap T \neq \emptyset] \geq \gamma_r$. Our proof will union bound over all $\binom{N}{m_r}$ choices of $T$.

    For any fixed $T$, define 
    \begin{equation*}
        A_T \coloneqq \set*{y: \Pr_{\bS \sim \mcD^{(r)}_y}\big[\bS \cap T \neq \emptyset\big] \leq \frac{\gamma_r}{2}} \quad\text{and}\quad  \Bad_T \coloneqq \set*{x: \Pr_{\bS \sim \mcD^{(r)}_x}\big[\bS \cap T \neq \emptyset\big] \geq \gamma_r}.
    \end{equation*}
    Our goal will be to show that each $\Bad_T$ is small enough that we can afford a union bound over all choices of $T$. We begin by showing that $A_T$ is large. Using the $\eta \le \gamma_r/(4m_r)$ regularity assumption,
    \begin{equation*}
        \Ex_{\by \sim \zo^N}\bracket*{\Ex_{\bS \sim \mcD^{(r)}_{\by}}\bracket*{\abs*{\bS \cap T}}} = \sum_{i \in T}\Ex_{\by \sim \zo^N}\bracket*{\Prx_{\bS \sim \mcD^{(r)}_{\by}}\bracket*{i \in \bS}} \leq \eta \cdot \abs*{T} \leq \frac{\gamma_r}{4}.
    \end{equation*}
    Therefore, by Markov's inequality, $\Pr[A_T] \geq \frac1{2}$.

    Next, we can apply \Cref{eq:dist-bound-layer} with the test $S \mapsto \Ind[S \cap T \neq \emptyset]$. This gives, for all $x \in \Bad_T$ and $y \in A_T$,
    \begin{equation*}
         \paren*{\sum_{r' \in [r-1]}\sqrt{\Prx_{\bS \sim \mcD^{(r')}_x}\bracket*{x_{\bS} \neq y_{\bS}}}}^2 \geq \Omega(\gamma_r).
    \end{equation*}
    By \Cref{claim:combine-dist-exp}, we have that
    \begin{equation*}
        \dist_{\mcD^{(\quads,r-1)}_x}(x, A_T) \geq c \gamma_r,
    \end{equation*}
    for some absolute constant $c > 0$. Using an appropriately large choice of constant in our assumption that 
    \begin{equation*}
        \gamma_r \geq \Omega\paren[\Bigg]{\sum_{r' \in [r-1]} \gamma_{r'} \cdot (r-r')^2}, 
    \end{equation*}

we can apply~\Cref{prop:combine-dist-hit} to get that
    \begin{equation*}
        x \in \Good^{(\leq r-1)} \implies \mcD^{(\quads,r-1)}_x\text{ is  }(m_{r-1},\lfrac{c}{2}\gamma_r)\text{-spread.} 
    \end{equation*}
  We now apply \Cref{lem:dist-to-hit} with $\tau = c\gamma_r$ and $\gamma = \frac{c}{2}\gamma_r$, along with the fact that $\mcD_x^{(\quads,r-1)}$ is supported on sets of size $O(t r^3)$:
    \begin{equation*}
        \Pr\bracket*{A_T} \cdot \Pr\bracket*{
           \Bad_T \cap \Good^{(\leq r-1)}} \leq \exp\paren*{-\Omega\paren*{\frac{\gamma_r m_{r-1} }{t r^3}}}. 
    \end{equation*}
     Finally, we observe that
    \begin{equation*}
        \Bad^{(r)}  \cap \Good^{(\leq r-1)} = \bigcup_{|T| = m_r} \Bad_T \cap \Good^{(\leq r-1)}.
    \end{equation*}
    The desired result follows from our earlier bound of $ \Pr\bracket*{A_T} \geq \frac1{2}$ for all choices of $T$ and a union bound over the $\binom{N}{m_r}$ choices of $T$.




\subsubsection{Proof of \Cref{claim:combine-dist-exp}}
\label{subsec:combine-dists}
\Cref{claim:combine-dist-exp} will follow straightforwardly from the following two propositions.
\begin{proposition} 
    \label{prop:exponential-sum}
     For any distributions $\mcD^{(1)},\ldots,\mcD^{(r)}$, and $x,y \in \zo^N,$
     \begin{equation*}
         \sum_{r' \in [r]} (r-r'+1)^2 \cdot \Prx_{\bS \sim \mcD^{(r')}_x}\bracket*{x_{\bS} \neq y_{\bS}} \geq \frac{6}{\pi^2} \cdot \paren[\Bigg]{\sum_{r' \in [r]}\sqrt{\Prx_{\bS \sim \mcD^{(r')}_x}\bracket*{x_{\bS} \neq y_{\bS}}}}^2
     \end{equation*}
\end{proposition}
\begin{proof}
    This is a straightforward application of Cauchy-Schwarz and convergence of $\sum_{i = 1}^{\infty} 1/i^2 = {\pi}^2/6$.
    \begin{align*}
        \paren*{\sum_{r' \in [r]}\sqrt{\Prx_{\bS \sim \mcD^{(r')}_x}\bracket*{x_{\bS} \neq y_{\bS}}}}^2 &= \paren*{\sum_{r'}\sqrt{(r - r' + 1)^{-2}} \cdot \sqrt{(r - r' + 1)^2\cdot\Prx_{\bS \sim \mcD^{(r')}_x}\bracket*{x_{\bS} \neq y_{\bS}}}}^2\\
        &\leq \paren*{\sum_{r'} (r-r'+1)^{-2}}\cdot \paren*{\sum_{r'}(r - r' + 1)^2\cdot\Prx_{\bS \sim \mcD^{(r')}_x}\bracket*{x_{\bS} \neq y_{\bS}}}\\
        &\leq \frac{\pi^2}{6} \cdot \sum_{r'} (r-r'+1)^2 \cdot \Prx_{\bS \sim \mcD^{(r')}_x}\bracket*{x_{\bS} \neq y_{\bS}}. \qedhere
    \end{align*}
\end{proof}

\begin{proposition}
    \label{prop:ind-sum}
    For any independent events $\bE_1, \ldots, \bE_m$,
    \begin{equation*}
        \Pr[\bE_1 \text{ or } \cdots \text{ or }\bE_m] \geq (1 - e^{-1}) \cdot \min\set[\Bigg]{1, \sum_{i \in [m]}\Pr[\bE_i]}.
    \end{equation*}
\end{proposition}
\begin{proof}
    Let $p_i = \Pr[\bE_i]$. Then,
    \begin{align*}
        \Pr[\bE_1 \text{ or } \cdots \text{ or }\bE_m] &= 1 - \prod_{i \in [m]}(1-p_i) \\
        &\geq 1 - e^{-\sum_{i \in [m]} p_i}.
    \end{align*}
    The desired result follows by the inequality $1 - e^{-P} \geq (1 - e^{-1}) \cdot \min\set{1, P}$ applied with $P = \sum_{i \in [m]} p_i$.
\end{proof}

We now combine these propositions.
\begin{proof}[Proof of \Cref{claim:combine-dist-exp}]
    First, we apply \Cref{prop:ind-sum} which gives
    \begin{equation*}
         \Prx_{\bS \sim \mcD^{(\quads,r)}_x}[x_{\bS} \neq y_{\bS}] \geq (1 - e^{-1}) \cdot \min\set*{1,\sum_{r' \in [r]} (r-r'+1)^2 \cdot \Prx_{\bS \sim \mcD^{(r')}_x}\bracket*{x_{\bS} \neq y_{\bS}}}.
    \end{equation*}
    The desired result then follows from \Cref{prop:exponential-sum} and the inequality $(1-e^{-1}) \cdot \frac{6}{\pi^2} \geq \frac1{3}$.
\end{proof}

\subsubsection{Proof of \Cref{prop:combine-dist-hit}}
\label{subsec:proof-of-combine-dist-hit}
    \begin{proof}
       Let $x \in \Good^{(\leq r)}$. We will show that 
        \begin{equation*}
            \Prx_{\bS \sim \mcD^{(\quads,r)}_x}[\bS \cap T \neq \emptyset] < \gamma
        \end{equation*}
        for any set $T$ of size $m_{r}$. Fix such a $T$.  
        Since $x \in \Good^{(\leq r)}$, it is not in $\Bad^{(1)},\ldots, \Bad^{(r)}$. Since $m_{r'}\ge m_r$ for all $r' \in [r]$, this means that
        \begin{equation*}
            \Prx_{\bS \sim \mcD^{(r')}_x}[\bS \cap T \neq \emptyset] < \gamma_{r'} \quad\quad\text{for all $r' \in [r]$}.
        \end{equation*}
    Then, by a union bound and the definition of $\mcD^{(\quads,r)}_x$ in \Cref{eq:def-quad-dist},
    \begin{align*}
         \Prx_{\bS \sim \mcD^{(\quads,r)}_x}[\bS \cap T \neq \emptyset] &\leq \sum_{r' \in [r]}(r-r'+1)^2 \cdot \Prx_{\bS \sim \mcD^{(r')}_x}[\bS \cap T \neq \emptyset] \\
         &< \sum_{r' \in [r]}(r-r'+1)^2 \cdot \gamma_{r'} = \gamma. \qedhere
    \end{align*}
\end{proof}

\subsection{Good inputs are biased: Proof of \Cref{lem:bound-var}}
\label{sec:lem:bound-var}
We can reuse many of the tools used in the proof of \Cref{lem:most-inputs-good}. 
For every $x\in \Rej$ and $y\in \Acc$, a combination of \Cref{eq:final_condition_implies_total_progress_2} and \Cref{claim:combine-dist-exp} gives
    \begin{equation*}
        \Prx_{\bS \sim \mcD_x^{(\quads, d)}}[x_{\bS} \neq y_{\bS}] \geq v  = \Omega(1) .
    \end{equation*}
That is, 
\begin{equation*}
    \dist_{\mcD_x^{(\quads, d)}}(x, \Acc) \geq v.
\end{equation*}
By \Cref{lem:dist-to-hit} and the fact that $\mcD_x^{(\quads, d)}$ is supported on sets of size $O(td^3)$,
    \begin{equation*}
        \Pr\big[\Acc\big] \cdot \Prx_{\bx}\Big[\bx\in\Rej\text{ and } \mcD_{\bx}^{(\quads, d)}\text{ is $(m_d, \lfrac1{2} v)$-spread}\Big] \leq \exp\paren*{-\Omega\paren*{\frac{m_d}{td^3}}}.
    \end{equation*}
    Finally \Cref{prop:combine-dist-hit} and \Cref{eq:sum-biased} together give that if $x \in \Good^{(\leq d)}$ then $\mcD_{x}^{(\quads, d)}$ is $(m_d, v/2)$-spread, giving the desired inequality.

\subsection{Putting things together: Proof of \Cref{thm:rsquared-bound}}
\label{sec:rsquared-bound}
    \paragraph{Setting parameters.} First we set the parameters $\gamma_1,\ldots, \gamma_d$ and $m_1,\ldots, m_d$. For some absolute constant $c$, we set
\[         \gamma_r = c^{-(d-r)} \quad\quad\text{and}\quad\quad m_r \coloneqq \log(1/\delta) \cdot (c td^3 \log N)^{d-r + 1} \cdot \prod_{r' = r+1}^d \frac{1}{\gamma_{r'}}.
   \] 
    Using these parameters, we set
    \begin{align*}
        \eta \coloneqq \frac{\gamma_1}{4m_1} &\geq \lfrac1{4} \cdot c^{-d} \cdot \paren*{\log(1/\delta) \cdot (ctd^3 \log N)^d \cdot \paren*{\frac{1}{\gamma_1}}^{d}}^{-1}\\
        &\geq 2^{-O(d^2)} \cdot (t \log N)^{-d} \cdot \log(1/\delta)^{-1}. \tag{Absorbing $(cd^3)^{-d}$ into $2^{-O(d^2)}$}
    \end{align*}

    \pparagraph{Bounding the size of the $\Bad$ sets.} We claim that
    \begin{equation}
        \Pr\bracket*{\Bad^{(r)} \cap \Good^{(\leq r-1)}} \leq \frac{\delta}{2d} \quad \text{for each $r\in [d]$,} \label{eq:each slice}
    \end{equation}
    where we take the convention that $\Good^{(\leq 0)} = \zo^N$ and otherwise follow the definitions in \Cref{eq:def-bad-good}. For $r = 1$, the distribution $\mcD^{(1)}_x$ does not depend on $x$ (\Cref{item:inital_condition_cor} of \Cref{cor:quantum-model}). Therefore, the assumption of $\eta$-regularity gives, for all $T$ and $x$,
    \begin{equation*}
        \Prx_{\bS \sim \mcD^{(1)}_x}[\bS \cap T \neq \emptyset] \leq \eta \cdot |T|.
    \end{equation*}
    For our choice of $\eta$, we therefore have that there is no $T$ of size $m_1$ that $\gamma_1$-hits $\mcD^{(1)}_x$, and so $\Bad^{(1)}$ is empty.

    For any $r \in \{2,\ldots,d\}$, we will apply \Cref{lem:most-inputs-good}. To do so, we need to verify that
    \begin{equation*}
        \gamma_r \geq \Omega\paren[\Bigg]{\sum_{r' \in [r-1]} \gamma_{r'} \cdot (r-r')^2},
    \end{equation*}
    which does indeed hold for a large enough choice of $c$ due to the convergence of the series $\sum_{k = 1}^\infty k^2/c^k$. Therefore,
    \begin{equation*}
          \Pr\bracket*{\Bad^{(r)} \cap \Good^{(\leq r-1)}} \leq  \binom{N}{m_r} \cdot\exp\paren*{-\Omega\paren*{\frac{\gamma_r m_{r-1}}{tr^3}}}.
    \end{equation*}
   For the RHS of the above to be at most $\frac{\delta}{2d}$ it suffices to ensure
    \begin{equation*}
         \exp\paren*{-\Omega\paren*{\frac{\gamma_r m_{r-1}}{tr^3}}} \leq \frac{\delta}{d \binom{N}{m_r}}.
    \end{equation*}
    Using the bound $\binom{N}{m} \leq N^m$ and solving for $m_{r-1}$, it in turn suffices to ensure
    \begin{equation*}
        m_{r-1} \geq \Omega\left(\frac{tr^3}{\gamma_r} \cdot \paren*{m_r \log N + \log(d/\delta)}\right),
    \end{equation*}
    which does indeed hold for our choice of parameters. Having shown~\Cref{eq:each slice}, a union bound over all $r \in [d]$ gives that
    \begin{equation*}
        \Pr\bracket*{\Good^{(\leq d)}} \geq 1 - \lfrac{\delta}{2}.
    \end{equation*}

    \pparagraph{$\Good$ inputs are biased.} This step is a direct application of \Cref{lem:bound-var}. First, we verify that, for our choice of parameters, \Cref{eq:sum-biased} holds. This is once again true due to convergence of the series $\sum_{k = 1}^\infty k^2/c^k$. Therefore, \Cref{lem:bound-var} gives
    \begin{equation*}
        \Pr\big[\Acc\big] \cdot \Pr\big[\Rej \cap \Good^{(\leq d)}\big] \leq \exp\paren*{-\Omega\paren*{\frac{m_d}{td^3}}},
    \end{equation*}
    which is at most $\delta/2$ by our choice of $m_d$. 

We have shown that 
\[ \Pr\big[\Acc\big]\cdot \Pr\big[\Rej\big] \le \Pr\big[\Acc\big]\cdot \Pr\big[\Rej \cap \Good^{(\le d)}\big] + \Pr\big[\Bad^{(\le d)}\big] \le \lfrac{\delta}{2} + \lfrac{\delta}{2} = \delta,  \]
and this completes the proof of~\Cref{thm:rsquared-bound}.

