\begin{equation}
2^{2\xi k}\left(\Vert [\Phi^{(k), 2}_{\mathcal{E}_u}\otimes \id](P^{EPR})\Vert_{\infty} + \Vert [\Phi^{(k), 3}_{\mathcal{E}_u}\otimes \id](P^{EPR})\Vert_{\infty}\right) \leq k!2^{k-\xi+1} + 3\sum_{T\in \Sigma_{k,k}\setminus S_k} f(T)^{2\xi/\ell},
