\section{Preliminaries}
\subsection{Basic quantum mechanics}
An isolated physical system is associated with a
Hilbert space is called the { state space}. A { pure state} of a
quantum system is a normalized vector in its state space, denoted by the Dirac notation $\ket{\varphi}$. A
{\it mixed state} is represented by a density operator on the inner product space with $\dotprodH{\rho}{\sigma} = \tr(\rho \sigma)$. Here, a density operator $\rho$ on $d$-dimensional Hilbert space $\C^d$ is a
positive semi-definite linear operator such that $\Tr(\rho)=1$.
We let
\begin{align*}
\mathcal{D}({\C^{d}})=\{\rho: \rho~\mathrm{is}~d\mathrm{-dimensional~density~operator~of~}\C^d\}
\end{align*}
denote the set of quantum states.

We use $I$, $X, Y$, and $Z$ to denote the Pauli matrices, the most important one-qubit matrix,
\begin{align*}
I=\begin{bmatrix}1 &0\\0&1\end{bmatrix}, X=\begin{bmatrix}0 &1\\1&0\end{bmatrix}, Z=\begin{bmatrix}1 &0\\0&-1\end{bmatrix}, Y=\begin{bmatrix}0 &i\\-i&0\end{bmatrix}.
\end{align*}

A important fact is that $\{I,X,Y,Z\}$ is a orthogonal basis for mixed states. Any mixed state $\rho$ can be written as
\begin{align*}
    \rho = \frac{\eye}{2} + \frac{\alpha_X}{2} X + \frac{\alpha_Y}{2} Y + \frac{\alpha_Z}{2} Z.
\end{align*}
We denote $\{\alpha_Q\}_{Q \in \{I,X,Y,Z\}}$ to be the \emph{Pauli decomposition} of $\rho$. Note, we fix $\alpha_\eye = \frac{1}{2}$ to ensure $\tr(\rho) = 1$ and $\sum_{P\in \{X,Y,Z\}} \alpha_P^2 \leq 1$ as a necessary condition for positive semi-definiteness.

\subsection{The tensor product of Hilbert space}

The state space of a composed quantum system is the tensor product of the state spaces of its component systems.
Let $\C^{d_k}$ be a Hilbert space. One can define a Hilbert space $\bigotimes_{k=1}^{n}\C^{d_k}$ as the tensor product of Hilbert spaces $\C^{d_k}$.
The following notation denotes the quantum state on the multipartite system $\bigotimes_{k=1}^{n}\C^{d_k}$,
\begin{align*}
\mathcal{D}(\otimes_{i=1}^{\nqubits}\C^{d_i})=\mathcal{D}(\C^{\Pi_{i=1}^{\nqubits} d_i}).
\end{align*}
An interesting consequence of tensor product is that a basis of $\mathcal{D}(\otimes_{i=1}^{\nqubits}\C^{d_i})$ can be written as the tensor product of the basis for each $\mathcal{D}(\C^{d_i})$. Namely, if we used the Pauli basis for a single-qubit, then $\mathcal{Q} = \{I,X,Y,Z\}^{\otimes \nqubits}$ serves as a basis for $\mathcal{D}(\C^d)$ when $d = 2^N$. Any $\nqubits$-qubit state $\rho \in \mathcal{D}(\mathbb{C}^d)$ can be written as
\begin{align*}
    \rho = \sum_{Q \in \mathcal{Q}} \frac{\alpha_Q}{d} Q.
\end{align*}
Here, we have the Pauli decomposition $\{\alpha_Q\}_{Q \in \mathcal{Q}}$ and similar constraints to the single-qubit decomposition with $\alpha_{I_d} = \frac{1}{d}$ and $\sum_{Q \in \mathcal{Q}} \alpha_Q^2 \leq d - 1$. We will call $\qmm = \frac{I_{d}}{d}$ the maximally mixed state of $\mathcal{D}(\C^{d})$. 

\subsection{Quantum measurement}

\paragraph{Positive operator-valued measures. } A positive operator-valued measure (POVM) is a measurement with non-negative self-adjoint operators in a Hilbert space $\C^{d}$, which is
described by a collection of matrices $\{M_i\}$ with $M_i\geq 0$ and
\begin{align*}\sum_{i}M_i=I_{d}.\end{align*}
If the state of a quantum system was $\rho$
 before measurement $\{M_i\}$ was performed,
the probability of $i$ occurring is
\begin{align*}p(i)=\dotprodH{M_i}{\rho} = \tr(M_i\rho).\end{align*}
A Hermitian $O=\sum_j \lambda_j \op{\psi_j}{\psi_j}$ (that is $O=O^{\dag}$) on $\mathcal{H}$ with orthonormal basis $\ket{\psi_j}$ and $\lambda_j\in\mathbb{R}$ always corresponds to the following measurement protocol.
Suppose the state of a quantum system is $\rho$ when measured in basis $\op{\psi_j}{\psi_j}$. If the outcome is $j$, the observed result is $\lambda_j$, and the output corresponds directly to a random variable $X$ such that
\begin{align*}
p(X=\lambda_j)&=\tr(\rho\op{\psi_j}{\psi_j}).
\end{align*}
We will denote the subset of POVMs that we are allowed to perform to be $\povmset$.

\paragraph{Measurement information channel.} The \emph{Measurement Information Channel} (MIC) describes the projected state after performing a POVM, and it serves as a vital object for quantifying the ``distinguishing power'' of a measurement.
\begin{definition} \label{def:mic}
Let $\POVM=\{M_x\}_{x \in \mathcal{X}}$ be a POVM. Then the Measurement Information Channel of $\POVM$ is defined as
\begin{align} 
    \Luders_\POVM(\rho) = \sum_{x} \frac{\dotprodH{M_x}{\rho} M_x}{\Tr[M_x]} = \sum_{x} \frac{\Tr(M_x \rho) M_x}{\Tr(M_x) }.
\end{align}
\end{definition}
\noindent The channel is a positive and trace-preserving map on $\mathcal{D}(\mathbb{C}^d)$.

\paragraph{Pauli Measurements.} For $U\in\{X,Y,Z\}$ with $U=\op{\psi_0}{\psi_0}-\op{\psi_1}{\psi_1}$, we use the Pauli measurement to denote the corresponding measurement,
\begin{align*}
M_+=\op{\psi_0}{\psi_0}, M_-=\op{\psi_1}{\psi_1}.
\end{align*}

For an $\nqubits$-qubit Pauli matrix $P=P_1P_2\cdots P_{\nqubits}\in \{I,X,Y,Z\}^{\otimes \nqubits}$ with $P\neq I^{\otimes \nqubits}$, we can always find orthogonal projections $Q_{+}$ and $Q_{-}$, i.e., $Q_{+}^2=Q_{+}$ and $Q_{-}^2=Q_{-}$, such that $P=Q_{+}-Q_{-}$ and $Q_{+}+Q_{-}= I^{\otimes \nqubits}$. Furthermore, the two outcome measurement
$\{Q_+,Q_-\}=\{\frac{I^{\otimes \nqubits}+P}{2},\frac{I^{\otimes \nqubits}-P}{2}\}$ can be implemented through the one-qubit Pauli measurements corresponding to $P = P_1 \otimes P_2 \otimes \ldots \otimes P_{\nqubits}$.

\medskip
\begin{observation}\label{observ}
For any
\[
P = P_1 \otimes P_2 \otimes \cdots \otimes P_{\nqubits}
\in \{X,Y,Z\}^{\otimes \nqubits},
\]
performing the measurement $P_i$ on the $i$-th qubit for each
$i\in[\nqubits]$ produces an $\nqubits$-bit outcome string $x \in \{-1,1\}^\nqubits$. The following POVM describes this Pauli basis measurement,
\begin{align*}
    M^{P}_x = \bigotimes_{i=1}^\nqubits \frac{I + x_i P_i}{2}.
\end{align*}

\noindent Moreover, the same outcome $x$ can also be interpreted as the
measurement outcome of any
\[
Q = Q_1 \otimes Q_2 \otimes \cdots \otimes Q_{\nqubits}
\in \{I,X,Y,Z\}^{\otimes \nqubits},
\]
provided that, for every $i\in[n]$, either $Q_i = P_i$ or
$Q_i = I$.
We say that such a Pauli operator $Q$ \emph{corresponds to} $P$, denoted as $Q\triangleleft P$. 

We will also denote $Q = P^{S}$ for $S \subseteq [\nqubits]$ to be the Pauli matrix where $Q_i = P_i$ if $i \in S$ and $Q_i = I$ otherwise and provide the shorthand $\alpha_P(S) = \alpha_{P^S}$. Indexing over all $S \subseteq [\nqubits]$ gives us all the Pauli operators that correspond to $P$.

\end{observation}

\subsection{Distances between states} \label{pre:dist}
\noindent For indexable set of numbers $t(i)$ for $i \in \mathcal{I}$, we refer to its $\ell_1$ norm as $\|t\|_1 = \sum_{i \in \mathcal{I}} |t(i)|$ and $\|t\|_2 = \sqrt{\sum_{i \in \mathcal{I}} |t(i)|^2}$ for its $\ell_2$ norm. Given a general operator $A$ with eigenvalues $\lambda_1, \ldots, \lambda_d$, the $\ell_1$ norm is defined as
\begin{align*}
||A||_1=\mathrm{Tr}|A| = \|\lambda\|_1,
\end{align*}
where $|A|\equiv\sqrt{A^\dag A}$ is the positive square root of $A^\dag A$. The $\ell_2$ norm is defined as
\begin{align*}
    ||A||_2=\sqrt{\mathrm{Tr}(A^2)} = \|\lambda\|_2.
\end{align*}
We denote the corresponding $\ell_1$ and $\ell_2$ distances to be $\|\rho - \sigma\|_1$ and $\|\rho - \sigma\|_2$, respectively.
The $\ell_2$ distance has a particularly nice form in terms of the Pauli coefficients due to the fact that $\mathcal{Q}$ (with normalization factor $\frac{1}{\sqrt{d}}$) form an orthogonal basis of $\mathcal{D}(\mathbb{C}^d)$. Let $\{\alpha_Q\}_{Q \in \mathcal{Q}}$ and $\{\beta_Q\}_{Q \in \mathcal{Q}}$ be the Pauli decompositions of $\rho$ and $\sigma$. Then,
\begin{align*}
    ||\rho-\sigma||_2^2 = \sum_{Q \in \mathcal{Q}} \frac{(\alpha_Q - \beta_Q)^2}{d} = \frac{1}{d} \|\alpha - \beta\|_2^2,
\end{align*}
For $\rho,\sigma\in\mathcal{D}(\C^{d})$, we have the following relation between $\ell_1$ and $\ell_2$ distances,
\begin{align*}
||\rho-\sigma||_2\leq ||\rho-\sigma||_1\leq \sqrt{d}||\rho-\sigma||_2 = \|\alpha-\beta\|_2.
\end{align*}
We also have the relation $\tracenorm{\rho - \sigma} \leq \sqrt{2r} \|\rho - \sigma\|_2 $ for $r = \max\{rank(\rho), rank(\sigma)\}$.
\subsection{Fourier analysis of Boolean Functions}
We will go over some basic facts regarding Fourier analysis of Boolean functions. For a more comprehensive review of the subject, we refer the reader to the excellent book \cite{odonnell2021analysisbooleanfunctions}.
\paragraph{Fourier Identities.} Consider a real-valued function on the Boolean hypercube $f: \{-1,1\}^\nqubits \rightarrow \mathbb{R}$. Define the parity functions on the hypercube as $\parity{x} \eqdef \prod_{s \in S} x_i$ for $S \subseteq [\nqubits]$. The parity functions serve as an orthogonal basis under the inner product space $\dotprodB{f}{g} \eqdef \expectDistrOf{\unif[\{-1,1\}^\nqubits]}{f(x)g(x)}$. Thus, $f$ can be uniquely expressed as a multi-linear polynomial:
\begin{align*}
    f(x) = \sum_{S \subseteq [N]} \alpha(S) \cdot \parity{x}.
\end{align*}
A consequence of these Fourier expansions is Parseval's Theorem. Given $g(x) = \sum_{S \subseteq [N]} \beta(S) \parity{x}$,
\begin{align*}
    \dotprod{f}{g}_{B} = \sum_{S \subseteq [\nqubits]} \alpha(S) \beta(S).
\end{align*}
Let's define the convolution of two functions $f * g (x) \eqdef \expectDistrOf{\unif[\{-1,1\}^\nqubits]}{f(y)g(x \oplus y)}$, where we denote $x \oplus y$ as element-wise multiplication. We have the following Fourier-analytic identity,
\begin{align*}
    f * g (x) = \sum_{S \subseteq [\nqubits]} \alpha(S) \beta(S) \cdot \parity{x}.
\end{align*}
\paragraph{Distributions on the Hypercube.} A distribution on the Boolean hypercube has the following Fourier expansion,
\begin{align*}
p(x) = \frac{1}{2^\nqubits} + \frac{1}{2^\nqubits} \sum_{\emptyset \subset S \subseteq [\nqubits]} \alpha(S) \cdot  \parity{x},
\end{align*}
where $\alpha(S) \in [-1,1]$ are chosen to guarantee non-negativity over $x \in \{-1,1\}^N$. The constraint $\alpha_{\emptyset} = 1$ is necessary to ensure normalization of the distribution. We denote $\|\alpha^{=k}\| \eqdef \sum_{|S| = k} \alpha(S)^2$ to be the total weight of the $k$-th order correlations. We provide a useful notion of concentration on coordinate-wise correlations.
\begin{definition}[$(\Delta,k, \beta)$-wise correlated distributions] For $\Delta, \beta \in (0,1]$, a distribution supported on $x \in \{-1,1\}^\nqubits$,
\begin{align*}
    p(x) =\frac{1}{2^\nqubits} + \frac{1}{2^\nqubits} \sum_{\emptyset \subset S \subseteq [\nqubits]} \parity{x} \alpha(S)
\end{align*}
is \emph{$(\Delta,k, \beta)$-wise correlated} if $\|\alpha^{=k}\|_2^2 \geq \beta\|\alpha\|_2^2$ and $\|\alpha^{=k}\|_2^2 \geq \beta \Delta$.
\end{definition}

\paragraph{Krawtchouk Polynomials.} Krawtchouk polynomials will serve as an important tool for testing correlations on the hypercube.
\begin{definition}[Krawtchouk Polynomials] For $t,k \in [N]$, the $k$-th order Krawtchouk Polynomial is defined as
\begin{align*}
    \krawt{k}{t} \eqdef \sum_{j=0}^k (-1)^j \binom{t}{j} \binom{N-t}{k-j}.
\end{align*}
\end{definition}
These polynomials arise in our testing subroutines as they express the Hamming weight symmetry of functions with constant $k$-th order correlations,
\begin{align} \label{eq:k-sym}
        f(x) = \sum_{|S| = k} \parity{x} = K_k^{(N)}(w_{H}(x)),
\end{align}
where $w_H(x)$ denotes the total number of $-1$'s in x. We also define the Hamming distance between two vectors: $d_H(x,y) \eqdef \sum_{i=1}^N 1^{(1-x_i \cdot y_i)} = w_H(x \oplus y)$.

