\title{Realizing Logical Diagonal Gates \\ via Transversal Physical $Z$-Rotations in CSS Codes$^\ast$}

\author{\NoCaseChange{
    K. Sai Mineesh Reddy and Navin Kashyap \\
    \textnormal{Electrical Communication Engineering Department, Indian Institute of Science, India} \\
