\title{Entanglement battery and entanglement catalyst in local state discrimination problems}

\author{Saronath Halder}
\affiliation{Department of Physics, School of Advanced Sciences, VIT-AP University, Beside AP Secretariat, Amaravati 522241, Andhra Pradesh, India}

